function goalWithdrawalForm(goalId){const goal=state.goals.find(item=>item.id===goalId);if(!goal)return;show(`<h2 class="formTitle">Hedeften para çek</h2><p class="formHint">Bu işlem yalnızca hedefe ayrılan tutarı azaltır; banka bakiyesine gelir yazmaz. Gerçek para hareketini gerekiyorsa ayrıca kaydedin.</p><p class="formHint">${esc(goal.name)} — kullanılabilir: ${money(goal.currentMinor/100)}</p><label class="field">Çekilecek tutar (TL)<input required name="amount" type="text" inputmode="decimal" placeholder="0,00"></label><label class="field">Tarih<input required name="date" type="date" value="${dateISO()}"></label><div class="formActions"><button>Çekimi kaydet</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async form=>{try{const amountMinor=FinanceCore.minor(form.get('amount'));if(amountMinor<=0||amountMinor>goal.currentMinor)throw new Error('Tutar sıfırdan büyük olmalı ve hedefteki birikimi aşmamalı.');const currentMinor=goal.currentMinor-amountMinor;await put('savingsGoals',{...goal,currentMinor,status:goal.status==='paused'?'paused':'active',updatedAt:dateISO()});await put('goalContributions',{id:id(),schemaVersion:1,goalId,amountMinor:-amountMinor,date:FinanceCore.date(form.get('date')),type:'withdrawal',createdAt:dateISO()});await load();toast('Hedeften çekim kaydedildi')}catch(error){toast(error.message||'Çekim kaydedilemedi.')}})}
