async function skipRecurring(recurringId){const recurring=state.recurring.find(item=>item.id===recurringId);if(!recurring||recurring.active===false)return;if(!confirm(`${recurring.name} için ${fmtDate(recurring.nextDueDate)} vadesi atlanacak. Gider kaydı oluşturulmaz. Devam edilsin mi?`))return;await put('recurringTransactions',{...recurring,nextDueDate:FinanceCore.nextOccurrence(recurring.nextDueDate,recurring.frequency),lastSkippedDate:recurring.nextDueDate,updatedAt:dateISO()});await load();toast('Vade atlandı; sonraki ödeme tarihi ilerletildi')}
