function refreshBudgetPace(){const pace=$('.pace');if(!pace)return;const month=dateISO().slice(0,7),today=new Date(),daysInMonth=new Date(today.getFullYear(),today.getMonth()+1,0).getDate(),daysLeft=Math.max(1,daysInMonth-today.getDate()+1),spentByCategory={};state.transactions.filter(transaction=>txType(transaction)==='expense'&&transaction.date.startsWith(month)&&(!transaction.planned||transaction.date<=dateISO())).forEach(transaction=>{const category=transaction.category||'Diğer';spentByCategory[category]=(spentByCategory[category]||0)+entryAmount(transaction.postings.find(posting=>posting.accountId==='expense')||{})});const budgets=state.budgets.filter(budget=>budget.active!==false),limit=budgets.reduce((total,budget)=>total+budget.limitMinor,0),spent=budgets.reduce((total,budget)=>total+(spentByCategory[budget.category]||0),0),remaining=limit-spent,title=pace.querySelector('b'),status=pace.querySelector('span');if(!limit){title.textContent='Önce aylık bütçe oluştur';status.textContent='● Limit yok';return}if(remaining<0){title.textContent=`${money(Math.abs(remaining)/100)} bütçe aşıldı`;status.textContent='● Dikkat gerekli';return}title.textContent=`Günde ${money(remaining/100/daysLeft)} harcama payın var`;status.textContent=`● ${daysLeft} gün kaldı`}
