function parseCsv(text){const delimiter=text.split(/\r?\n/,1)[0].includes(';')?';':',',rows=[],row=[],state={value:'',quoted:false};for(let index=0;index<text.length;index++){const char=text[index],next=text[index+1];if(state.quoted){if(char==='"'&&next==='"'){state.value+='"';index++}else if(char==='"')state.quoted=false;else state.value+=char;continue}if(char==='"'){state.quoted=true;continue}if(char===delimiter){row.push(state.value);state.value='';continue}if(char==='\n'){row.push(state.value.replace(/\r$/,''));rows.push([...row]);row.length=0;state.value='';continue}state.value+=char}if(state.value||row.length){row.push(state.value.replace(/\r$/,''));rows.push(row)}return rows}
function importSignature(transaction){const negative=transaction.postings.find(posting=>entryAmount(posting)<0),positive=transaction.postings.find(posting=>entryAmount(posting)>0),amount=Math.round(Math.abs(entryAmount(negative||positive||{}))*100);return [transaction.date,transaction.note||'',transaction.category||'',negative?.accountId||'',positive?.accountId||'',amount,Boolean(transaction.planned)].join('|')}
async function previewCsvImport(file){try{const raw=(await file.text()).replace(/^\uFEFF/,''),rows=parseCsv(raw);if(rows.length<2)throw new Error('Dosyada içe aktarılacak satır bulunamadı.');const headers=rows.shift().map(header=>header.trim()),expected=['Tarih','Açıklama','Kategori','Tür','Kaynak','Hedef','Tutar (TL)','Planlı'];if(expected.some((header,index)=>headers[index]!==header))throw new Error('Bu dosya Cep Finans CSV dışa aktarma biçiminde değil.');const byName=new Map([...state.accounts.map(account=>[account.name,account.id]),['Gelir','income'],['Gider','expense']]),existing=new Set(state.transactions.map(importSignature)),valid=[],errors=[];for(let index=0;index<rows.length;index++){const row=rows[index];if(!row.some(value=>value.trim()))continue;try{const [date,note,category,type,sourceName,targetName,amountText,plannedText]=row,dateValue=FinanceCore.date(date),amountMinor=FinanceCore.minor(amountText),source=byName.get(sourceName),target=byName.get(targetName);if(!Number.isSafeInteger(amountMinor)||amountMinor<=0)throw new Error('Tutar geçersiz.');if(!source||!target||source===target)throw new Error('Kaynak veya hedef hesap bulunamadı.');const postings=FinanceCore.ledger([{accountId:source,amountMinor:-amountMinor},{accountId:target,amountMinor}]).map(posting=>({...posting,amount:posting.amountMinor/100})),transaction={id:id(),schemaVersion:2,date:dateValue,note:String(note||'').trim(),category:String(category||'').trim(),postings,planned:String(plannedText||'').trim()==='Evet',importedAt:dateISO()};if(existing.has(importSignature(transaction)))continue;existing.add(importSignature(transaction));valid.push(transaction)}catch(error){errors.push(`Satır ${index+2}: ${error.message||'geçersiz kayıt'}`)}}if(!valid.length){toast(errors.length?'Yeni, geçerli kayıt bulunamadı.':'Dosyada yeni kayıt yok.');return}const preview=valid.slice(0,6).map(transaction=>`<li>${esc(fmtDate(transaction.date))} — ${esc(transaction.note||'İsimsiz hareket')}</li>`).join('');show(`<h2 class="formTitle">CSV içe aktarma önizlemesi</h2><p class="formHint">${valid.length} yeni hareket eklenecek. ${rows.length-valid.length-errors.length} yinelenen satır atlandı.${errors.length?` ${errors.length} satır geçersiz.`:''}</p><ul class="formHint">${preview}${valid.length>6?'<li>…</li>':''}</ul><div class="formActions"><button>İçe aktar</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async()=>{await putMany('transactions',valid);await load();toast(`${valid.length} hareket güvenle içe aktarıldı`)})}catch(error){toast(error.message||'CSV dosyası okunamadı.')}}
function setupCsvImport(){const csvExport=$('#csvExportBtn');if(!csvExport||$('#csvImportFile'))return;const label=document.createElement('label');label.className='secondary-btn';label.textContent='Cep Finans CSV içe aktar';const input=document.createElement('input');input.id='csvImportFile';input.type='file';input.accept='.csv,text/csv';input.hidden=true;input.onchange=async event=>{const file=event.target.files?.[0];if(file)await previewCsvImport(file);event.target.value=''};label.append(input);csvExport.before(label)}
