function renderAnalyticsHistory(){const chart=$('.bar-chart');if(!chart)return;const base=`${dateISO().slice(0,8)}01`,rows=[];for(let offset=7;offset>=0;offset--){const month=FinanceCore.addMonths(base,-offset).slice(0,7),amount=state.transactions.filter(transaction=>transaction.date.startsWith(month)&&txType(transaction)==='expense'&&(!transaction.planned||transaction.date<=dateISO())).reduce((total,transaction)=>total+entryAmount(transaction.postings.find(posting=>posting.accountId==='expense')||{}),0);rows.push({month,amount})}const maximum=Math.max(1,...rows.map(row=>row.amount));chart.innerHTML=rows.map(row=>`<i style="height:${row.amount?Math.max(6,Math.round(row.amount/maximum*100)):4}%" title="${new Date(`${row.month}-01T12:00`).toLocaleDateString('tr-TR',{month:'short',year:'numeric'})}: ${money(row.amount)}" aria-label="${row.month} ${money(row.amount)}"></i>`).join('')}
