async function deleteInstallmentGroup(groupId){const count=state.transactions.filter(t=>t.installmentGroup===groupId).length;if(!confirm(`Bu taksit grubundaki ${count} kayıt silinsin mi? Kart borcu ve planlanan taksitler buna göre yeniden hesaplanır.`))return;for(const transaction of state.transactions.filter(t=>t.installmentGroup===groupId))await remove('transactions',transaction.id);await remove('cardPurchases',groupId);await load();toast('Taksit grubu silindi')}
