async function backup(){const snapshot={version:3,createdAt:new Date().toISOString()};for(const storeName of BACKUP_STORES)snapshot[storeName]=storeName==='accounts'?state.accounts:storeName==='transactions'?state.transactions:await all(storeName);if(!BACKUP_STORES.some(storeName=>snapshot[storeName].length)){toast('Yedeklenecek kayıt yok.');return}let pass=prompt('Yedek parolasını belirleyin. Bu parola olmadan geri yüklenemez.');if(!pass)return;let confirm=prompt('Parolayı tekrar girin.');if(pass!==confirm){toast('Parolalar eşleşmiyor.');return}let salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await derive(pass,salt),plain=new TextEncoder().encode(JSON.stringify(snapshot)),encrypted=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,plain),data={format:'cep-finans-backup',version:3,kdf:'PBKDF2-SHA-256',iterations:250000,salt:b64(salt),iv:b64(iv),ciphertext:b64(new Uint8Array(encrypted))};download(JSON.stringify(data),'cep-finans-yedek-'+dateISO()+'.cepfinans');toast('Tüm verileri içeren şifreli yedek indirildi')}
