function exportCsv(){const quote=value=>`"${String(value??'').replace(/"/g,'""')}"`,rows=[['Tarih','Açıklama','Kategori','Tür','Kaynak','Hedef','Tutar (TL)','Planlı']];for(const t of state.transactions){let source=t.postings.find(p=>entryAmount(p)<0),target=t.postings.find(p=>entryAmount(p)>0),amount=Math.abs(entryAmount(source||target||{})),type=txType(t);rows.push([t.date,t.note||'',t.category||'',type,accountName(source?.accountId),accountName(target?.accountId),amount.toFixed(2).replace('.',','),t.planned?'Evet':'Hayır'])}const csv='\uFEFF'+rows.map(row=>row.map(quote).join(';')).join('\r\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`cep-finans-hareketler-${dateISO()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('CSV dışa aktarıldı')}
