function applyDynamicCategories(){document.querySelectorAll('#formContent select[name="category"],#formContent select[name^="category"]').forEach(select=>{if(select.dataset.dynamicCategories==='ready')return;const selected=select.value||'Diğer',items=[...new Set([...availableCategories(),selected])];select.innerHTML=items.map(name=>`<option value="${esc(name)}" ${name===selected?'selected':''}>${esc(name)}</option>`).join('');select.dataset.dynamicCategories='ready'})}
new MutationObserver(applyDynamicCategories).observe(document.body,{childList:true,subtree:true});
function categoryManager(){const rows=state.categories.length?state.categories.sort((a,b)=>a.name.localeCompare(b.name,'tr')).map(item=>`<div class="budget-row"><b><span>${esc(item.name)}</span><span>${item.active===false?'Durduruldu':'Etkin'}</span></b><small>${item.active===false?'Yeni kayıtlarda görünmez; geçmiş hareketler korunur.':'İşlem ve bütçe formlarında kullanılabilir.'}</small><button type="button" class="textButton" data-category-toggle="${item.id}">${item.active===false?'Etkinleştir':'Durdur'}</button></div>`).join(''):'<div class="budget-row"><b>Özel kategori yok</b><small>Varsayılan kategorilere kendi kategorilerinizi ekleyin.</small></div>';show(`<h2 class="formTitle">Kategorileri yönet</h2><p class="formHint">Varsayılan kategoriler korunur. Özel kategoriyi durdurmak geçmiş kayıtları değiştirmez.</p>${rows}<div class="formActions"><button type="button" data-category-add>Yeni kategori</button><button type="button" onclick="document.getElementById('modal').close()">Kapat</button></div>`,async()=>{})}
function categoryForm(){show(`<h2 class="formTitle">Yeni kategori</h2><label class="field">Kategori adı<input required name="name" maxlength="50" placeholder="Örn. Evcil hayvan"></label><div class="formActions"><button>Kaydet</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async form=>{try{const name=String(form.get('name')||'').trim();if(!name)throw new Error('Kategori adı gerekli.');const duplicate=[...DEFAULT_CATEGORIES,...state.categories.map(item=>item.name)].some(item=>item.localeCompare(name,'tr',{sensitivity:'accent'})===0);if(duplicate)throw new Error('Bu kategori zaten var.');await put('categories',{id:id(),schemaVersion:1,name,active:true,createdAt:new Date().toISOString()});await load();toast('Özel kategori eklendi')}catch(error){toast(error.message||'Kategori kaydedilemedi.')}})}
async function toggleCategory(categoryId){const category=state.categories.find(item=>item.id===categoryId);if(!category)return;await put('categories',{...category,active:category.active===false,updatedAt:new Date().toISOString()});await load();categoryManager()}
function renderCategoryManager(){const more=$('#more');if(!more||$('#categoryManagerCard'))return;const card=document.createElement('article');card.id='categoryManagerCard';card.className='settings-card';card.innerHTML='<i>◌</i><div><h2>Kategoriler</h2><p>Özel kategori ekleyin ve kullanımı yönetin.</p></div><button type="button" class="textButton" data-category-manager>Yönet</button>';const privacy=more.querySelector('.privacy');if(privacy)more.insertBefore(card,privacy);else more.append(card)}
const cepFinansRenderWithStatements=render;render=function(){cepFinansRenderWithStatements();renderCategoryManager()};
document.addEventListener('click',event=>{const manager=event.target.closest?.('[data-category-manager]'),add=event.target.closest?.('[data-category-add]'),toggle=event.target.closest?.('[data-category-toggle]');if(manager){event.preventDefault();event.stopImmediatePropagation();categoryManager();return}if(add){event.preventDefault();event.stopImmediatePropagation();categoryForm();return}if(toggle){event.preventDefault();event.stopImmediatePropagation();toggleCategory(toggle.dataset.categoryToggle)}},true);

/* 12 aylık tahmin senaryoları: kayıtlar değişmeden yalnızca görünümü etkiler. */
function currentForecastScenario(){return activeForecastScenario==='base'?null:state.forecastScenarios.find(item=>item.id===activeForecastScenario)||null}
function scenarioMonthlyDelta(){const scenario=currentForecastScenario();return scenario?(scenario.monthlyIncomeMinor-scenario.monthlyExpenseMinor)/100:0}
function renderForecast(){const cashAccounts=state.accounts.filter(account=>isLiquidAccount(account)&&!account.archivedAt&&account.includeInTotals!==false),scenarioDelta=scenarioMonthlyDelta();let html='',base=cashAccounts.reduce((total,account)=>total+accountBalance(account),0),max=1,rows=[];for(let index=0;index<12;index++){const monthStart=FinanceCore.addMonths(dateISO().slice(0,8)+'01',index),key=monthStart.slice(0,7),plannedDelta=state.transactions.filter(transaction=>transaction.planned&&transaction.date>dateISO()&&transaction.date.startsWith(key)).reduce((total,transaction)=>total+transaction.postings.filter(posting=>cashAccounts.some(account=>account.id===posting.accountId)).reduce((sum,posting)=>sum+entryAmount(posting),0),0)-recurringDueMinor(key)/100;base+=plannedDelta+scenarioDelta;rows.push({monthStart,base});max=Math.max(max,...rows.map(row=>Math.abs(row.base)))}for(const row of rows){const [year,month]=row.monthStart.split('-');html+=`<div class="month"><span>${new Date(Number(year),Number(month)-1,1).toLocaleDateString('tr-TR',{month:'short',year:'2-digit'})}</span><div class="bar"><i style="width:${Math.max(3,Math.abs(row.base)/max*100)}%"></i></div><b>${money(row.base)}</b></div>`}$('#forecast').innerHTML=html}
function scenarioForm(scenarioId){const existing=scenarioId?state.forecastScenarios.find(item=>item.id===scenarioId):null,income=existing?(existing.monthlyIncomeMinor/100).toFixed(2).replace('.',','):'0,00',expense=existing?(existing.monthlyExpenseMinor/100).toFixed(2).replace('.',','):'0,00';show(`<h2 class="formTitle">${existing?'Senaryoyu düzenle':'Tahmin senaryosu'}</h2><p class="formHint">Senaryo mevcut kayıtları değiştirmez; yalnızca 12 aylık nakit akışı görünümüne aylık varsayım ekler.</p><label class="field">Senaryo adı<input required name="name" maxlength="60" value="${esc(existing?.name||'')}" placeholder="Örn. İyimser"></label><label class="field">Aylık ek gelir (TL)<input required name="income" type="text" inputmode="decimal" value="${income}"></label><label class="field">Aylık ek gider (TL)<input required name="expense" type="text" inputmode="decimal" value="${expense}"></label><div class="formActions"><button>Kaydet</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async form=>{try{const name=String(form.get('name')||'').trim(),monthlyIncomeMinor=FinanceCore.minor(form.get('income')),monthlyExpenseMinor=FinanceCore.minor(form.get('expense'));if(!name||monthlyIncomeMinor<0||monthlyExpenseMinor<0)throw new Error('Geçerli senaryo bilgileri girin.');await put('forecastScenarios',{id:existing?.id||id(),schemaVersion:1,name,monthlyIncomeMinor,monthlyExpenseMinor,updatedAt:new Date().toISOString()});await load();toast('Tahmin senaryosu kaydedildi')}catch(error){toast(error.message||'Senaryo kaydedilemedi.')}})}
function renderScenarioControls(){const analytics=$('#analytics');if(!analytics)return;let card=$('#scenarioCard');if(!card){card=document.createElement('article');card.id='scenarioCard';card.className='glass-card';card.innerHTML='<div class="ledger-head"><div><div class="eyebrow">NAKİT AKIŞI SENARYOSU</div><h2>12 aylık tahmin</h2></div><select id="forecastScenarioSelect" aria-label="Tahmin senaryosu"></select></div><p id="forecastScenarioDetail" class="formHint"></p><div class="formActions"><button type="button" data-scenario-add>Yeni senaryo</button><button type="button" data-scenario-edit>Düzenle</button></div>';const forecast=$('#forecast');if(forecast)analytics.insertBefore(card,forecast);card.querySelector('#forecastScenarioSelect').onchange=event=>{activeForecastScenario=event.target.value;render()}}const select=$('#forecastScenarioSelect'),scenarios=[{id:'base',name:'Mevcut plan'}].concat(state.forecastScenarios);select.innerHTML=scenarios.map(item=>`<option value="${item.id}" ${item.id===activeForecastScenario?'selected':''}>${esc(item.name)}</option>`).join('');if(!scenarios.some(item=>item.id===activeForecastScenario)){activeForecastScenario='base';select.value='base'}const scenario=currentForecastScenario(),detail=$('#forecastScenarioDetail');detail.textContent=scenario?`Aylık varsayım: ${money(scenario.monthlyIncomeMinor/100)} ek gelir • ${money(scenario.monthlyExpenseMinor/100)} ek gider.`:'Mevcut planlı kayıtlar, taksitler ve düzenli ödemeler üzerinden hesaplanır.';const edit=card.querySelector('[data-scenario-edit]');edit.disabled=!scenario;edit.dataset.scenarioEdit=scenario?.id||''}
const cepFinansRenderWithCategories=render;render=function(){cepFinansRenderWithCategories();renderScenarioControls()};
document.addEventListener('click',event=>{const add=event.target.closest?.('[data-scenario-add]'),edit=event.target.closest?.('[data-scenario-edit]');if(add){event.preventDefault();event.stopImmediatePropagation();scenarioForm();return}if(edit&&!edit.disabled){event.preventDefault();event.stopImmediatePropagation();scenarioForm(edit.dataset.scenarioEdit)}},true);

/* Hatırlatmalar yalnızca bu cihazdaki kayıtlarla hesaplanır. Bildirim izni
   kullanıcı dokunmadan istenmez; izin verilmezse uygulama içi özet sürer. */
let reminderSummaryShown=false;
function upcomingReminderEvents(){const start=dateISO(),events=[];for(let day=0;day<8;day++){const current=new Date(`${start}T12:00`);current.setDate(current.getDate()+day);const date=`${current.getFullYear()}-${String(current.getMonth()+1).padStart(2,'0')}-${String(current.getDate()).padStart(2,'0')}`;for(const recurring of state.recurring.filter(item=>item.active!==false&&item.nextDueDate===date))events.push({date,title:recurring.name,amountMinor:recurring.amountMinor});for(const debt of [...state.debts,...state.loans].filter(item=>item.active!==false&&item.nextDueDate===date))events.push({date,title:debt.name,amountMinor:debt.monthlyPaymentMinor});for(const card of state.accounts.filter(item=>item.type==='card'&&item.closingDay)){const cycle=FinanceCore.cardCycleWithDueOffset(date,card.closingDay,10,Boolean(card.closingDayPurchasesNext));if(cycle.dueDate===date)events.push({date,title:card.name,amountMinor:0})}}return events.sort((a,b)=>a.date.localeCompare(b.date))}
function showReminderSummary(){if(reminderSummaryShown)return;reminderSummaryShown=true;const events=upcomingReminderEvents();if(!events.length)return;const first=events[0],days=Math.max(0,Math.round((new Date(`${first.date}T12:00`)-new Date(`${dateISO()}T12:00`))/86400000));toast(`${days?'Yaklaşan ödeme:':'Bugün ödeme:'} ${first.title}${first.amountMinor?` • ${money(first.amountMinor/100)}`:''}`);if(localStorage.getItem('cepFinansNotifications')==='enabled'&&'Notification'in window&&Notification.permission==='granted')new Notification('Cep Finans',{body:`${first.title}${first.amountMinor?` • ${money(first.amountMinor/100)}`:''}`})}
function renderReminderControl(){const more=$('#more');if(!more||$('#reminderCard'))return;const enabled=localStorage.getItem('cepFinansNotifications')==='enabled',permission='Notification'in window?Notification.permission:'unsupported',card=document.createElement('article');card.id='reminderCard';card.className='settings-card';card.innerHTML=`<i>◷</i><div><h2>Ödeme hatırlatmaları</h2><p>${enabled&&permission==='granted'?'Bildirimler etkin.':'Uygulama açıldığında yaklaşan ödemeler gösterilir.'}</p></div><button type="button" class="textButton" data-reminder-enable>${enabled&&permission==='granted'?'Etkin':'Etkinleştir'}</button>`;const privacy=more.querySelector('.privacy');if(privacy)more.insertBefore(card,privacy);else more.append(card)}
const cepFinansRenderWithScenarios=render;render=function(){cepFinansRenderWithScenarios();renderReminderControl();showReminderSummary()};
document.addEventListener('click',async event=>{const button=event.target.closest?.('[data-reminder-enable]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();if(!('Notification'in window)){toast('Bu tarayıcı bildirim iznini desteklemiyor.');return}const permission=await Notification.requestPermission();if(permission==='granted'){localStorage.setItem('cepFinansNotifications','enabled');toast('Ödeme bildirimleri etkinleştirildi.')}else{localStorage.removeItem('cepFinansNotifications');toast('Bildirim izni verilmedi; uygulama içi özet kullanılacak.')}render()},true);

function amortizationForm(debtId){const debt=[...state.debts,...state.loans].find(item=>item.id===debtId);if(!debt||debt.direction==='incoming')return;const rate=((debt.annualRateBps||0)/100).toFixed(2).replace('.',',');show(`<h2 class="formTitle">Kredi amortismanı</h2><p class="formHint">${esc(debt.name)} için faiz oranını girin. Bu hesap plan görünümüdür; gerçek para hareketi oluşturmaz.</p><label class="field">Yıllık faiz oranı (%)<input required name="rate" type="text" inputmode="decimal" value="${rate}"></label><div class="formActions"><button>Tabloyu göster</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async form=>{try{const annualRateBps=FinanceCore.minor(form.get('rate'));if(annualRateBps<0)throw new Error('Faiz oranı negatif olamaz.');await put('debts',{...debt,annualRateBps,updatedAt:dateISO()});await load();setTimeout(()=>showAmortization(debtId),0)}catch(error){toast(error.message||'Faiz oranı kaydedilemedi.')}})}
function showAmortization(debtId){const debt=[...state.debts,...state.loans].find(item=>item.id===debtId);if(!debt)return;try{const rows=FinanceCore.amortization(debt.remainingMinor,debt.monthlyPaymentMinor,debt.annualRateBps||0,Math.max(1,debt.remainingInstallments||600)),preview=rows.slice(0,12).map(row=>`<div class="budget-row"><b><span>${row.period}. vade</span><span>${money(row.paymentMinor/100)}</span></b><small>Anapara: ${money(row.principalMinor/100)} • Faiz: ${money(row.interestMinor/100)} • Kalan: ${money(row.remainingMinor/100)}</small></div>`).join('');show(`<h2 class="formTitle">${esc(debt.name)} amortismanı</h2><p class="formHint">Yıllık faiz: ${((debt.annualRateBps||0)/100).toLocaleString('tr-TR',{minimumFractionDigits:2})}% • Toplam ${rows.length} vade</p>${preview}${rows.length>12?`<p class="formHint">İlk 12 vade gösteriliyor.</p>`:''}<div class="formActions"><button type="button" onclick="document.getElementById('modal').close()">Kapat</button></div>`,async()=>{})}catch(error){toast(error.message||'Amortisman hesaplanamadı.')}}
function renderAmortizationControls(){document.querySelectorAll('[data-debt-settle]').forEach(row=>{const debt=[...state.debts,...state.loans].find(item=>item.id===row.dataset.debtSettle);if(!debt||debt.direction==='incoming'||row.querySelector('[data-debt-amortization]'))return;const button=document.createElement('button');button.type='button';button.className='textButton';button.dataset.debtAmortization=debt.id;button.textContent='Faiz / amortisman';row.append(button)})}
const cepFinansRenderWithReminders=render;render=function(){cepFinansRenderWithReminders();renderAmortizationControls()};
document.addEventListener('click',event=>{const button=event.target.closest?.('[data-debt-amortization]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();amortizationForm(button.dataset.debtAmortization)},true);

/* Görünüm tercihi finansal veri değildir; cihazda saklanır ve sistem temasını izleyebilir. */
const themeStyle=document.createElement('style');themeStyle.textContent=':root[data-theme="light"]{--bg:#f4f6f2;--low:#e8ece6;--card:rgba(255,255,255,.9);--high:#dde3db;--text:#172019;--muted:#5c6b60;--green:#087a32;--green2:#22a851;--coral:#b54538;--lilac:#5954a8;--line:rgba(20,55,28,.13)}@media(prefers-color-scheme:light){:root[data-theme="system"]{--bg:#f4f6f2;--low:#e8ece6;--card:rgba(255,255,255,.9);--high:#dde3db;--text:#172019;--muted:#5c6b60;--green:#087a32;--green2:#22a851;--coral:#b54538;--lilac:#5954a8;--line:rgba(20,55,28,.13)}}';document.head.append(themeStyle);
function selectedTheme(){return localStorage.getItem('cepFinansTheme')||'system'}
function applyTheme(theme=selectedTheme()){document.documentElement.dataset.theme=theme;localStorage.setItem('cepFinansTheme',theme)}
applyTheme();
function renderThemeControl(){const more=$('#more');if(!more||$('#themeCard'))return;const theme=selectedTheme(),card=document.createElement('article');card.id='themeCard';card.className='settings-card';card.innerHTML=`<i>◐</i><div><h2>Görünüm</h2><p>${theme==='system'?'Cihaz temasını izliyor.':theme==='light'?'Açık tema etkin.':'Koyu tema etkin.'}</p></div><button type="button" class="textButton" data-theme-cycle>Tema</button>`;const privacy=more.querySelector('.privacy');if(privacy)more.insertBefore(card,privacy);else more.append(card)}
const cepFinansRenderWithAmortization=render;render=function(){cepFinansRenderWithAmortization();renderThemeControl()};
document.addEventListener('click',event=>{const button=event.target.closest?.('[data-theme-cycle]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();const options=['system','light','dark'],next=options[(options.indexOf(selectedTheme())+1)%options.length];applyTheme(next);const card=$('#themeCard');if(card)card.remove();renderThemeControl();toast(next==='system'?'Sistem teması etkin.':next==='light'?'Açık tema etkin.':'Koyu tema etkin.')},true);

/* v41: makbuzlar, alt kategoriler ve banka CSV içe aktarımı. Tüm dosyalar yalnızca IndexedDB'de tutulur. */
function subcategoriesFor(parent){return state.subcategories.filter(item=>item.parentCategory===parent&&item.active!==false).sort((a,b)=>a.name.localeCompare(b.name,'tr'))}
function refreshSubcategorySelect(){const category=$('#formContent select[name="category"]'),select=$('#formContent select[name="subcategory"]');if(!category||!select)return;const selected=select.value||'',items=subcategoriesFor(category.value);select.innerHTML=`<option value="">Alt kategori yok</option>${items.map(item=>`<option value="${esc(item.name)}" ${item.name===selected?'selected':''}>${esc(item.name)}</option>`).join('')}`}
function enhancedCategoryManager(){const categoryRows=state.categories.length?state.categories.slice().sort((a,b)=>a.name.localeCompare(b.name,'tr')).map(item=>`<div class="budget-row"><b><span>${esc(item.name)}</span><span>${item.active===false?'Durduruldu':'Etkin'}</span></b><small>Özel ana kategori</small><button type="button" class="textButton" data-category-toggle="${item.id}">${item.active===false?'Etkinleştir':'Durdur'}</button></div>`).join(''):'<div class="budget-row"><b>Özel ana kategori yok</b><small>Varsayılan ana kategoriler kullanılabilir.</small></div>';
const subRows=state.subcategories.length?state.subcategories.slice().sort((a,b)=>`${a.parentCategory}/${a.name}`.localeCompare(`${b.parentCategory}/${b.name}`,'tr')).map(item=>`<div class="budget-row"><b><span>${esc(item.parentCategory)} › ${esc(item.name)}</span><span>${item.active===false?'Durduruldu':'Etkin'}</span></b><small>Geçmiş hareketler korunur.</small><button type="button" class="textButton" data-subcategory-toggle="${item.id}">${item.active===false?'Etkinleştir':'Durdur'}</button></div>`).join(''):'<div class="budget-row"><b>Alt kategori yok</b><small>Örn. Market › Temizlik şeklinde ayrıntı ekleyebilirsiniz.</small></div>';
show(`<h2 class="formTitle">Kategorileri yönet</h2><p class="formHint">Durdurulan kategori yeni kayıtlarda görünmez; geçmiş hareketler asla değişmez.</p><h3 class="formTitle" style="font-size:16px">Ana kategoriler</h3>${categoryRows}<h3 class="formTitle" style="font-size:16px;margin-top:16px">Alt kategoriler</h3>${subRows}<div class="formActions"><button type="button" data-category-add>Yeni ana kategori</button><button type="button" data-subcategory-add>Yeni alt kategori</button><button type="button" onclick="document.getElementById('modal').close()">Kapat</button></div>`,async()=>{})}
function subcategoryForm(){const parents=availableCategories();show(`<h2 class="formTitle">Yeni alt kategori</h2><label class="field">Ana kategori<select required name="parentCategory">${parents.map(name=>`<option value="${esc(name)}">${esc(name)}</option>`).join('')}</select></label><label class="field">Alt kategori adı<input required name="name" maxlength="50" placeholder="Örn. Temizlik"></label><div class="formActions"><button>Kaydet</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async form=>{try{const parentCategory=String(form.get('parentCategory')||''),name=String(form.get('name')||'').trim();if(!parentCategory||!name)throw new Error('Ana kategori ve alt kategori adı gerekli.');if(state.subcategories.some(item=>item.parentCategory===parentCategory&&item.name.localeCompare(name,'tr',{sensitivity:'accent'})===0))throw new Error('Bu alt kategori zaten var.');await put('subcategories',{id:id(),schemaVersion:1,parentCategory,name,active:true,createdAt:new Date().toISOString()});await load();toast('Alt kategori eklendi')}catch(error){toast(error.message||'Alt kategori kaydedilemedi.')}})}
async function toggleSubcategory(subcategoryId){const item=state.subcategories.find(row=>row.id===subcategoryId);if(!item)return;await put('subcategories',{...item,active:item.active===false,updatedAt:dateISO()});await load();enhancedCategoryManager()}
categoryManager=enhancedCategoryManager;
document.addEventListener('click',event=>{const manager=event.target.closest?.('[data-category-manager]'),subAdd=event.target.closest?.('[data-subcategory-add]'),subToggle=event.target.closest?.('[data-subcategory-toggle]');if(manager){event.preventDefault();event.stopImmediatePropagation();enhancedCategoryManager();return}if(subAdd){event.preventDefault();event.stopImmediatePropagation();subcategoryForm();return}if(subToggle){event.preventDefault();event.stopImmediatePropagation();toggleSubcategory(subToggle.dataset.subcategoryToggle)}},true);

function attachmentRows(transactionId){const records=state.attachments.filter(item=>item.transactionId===transactionId);if(!records.length)return '<p class="formHint">Bu harekete eklenmiş makbuz yok.</p>';return records.map(item=>`<div class="budget-row"><b><span>${esc(item.name||'Makbuz')}</span><span>${Math.ceil((item.size||0)/1024)} KB</span></b><button type="button" class="textButton" data-attachment-open="${item.id}">Aç</button><button type="button" class="textButton" data-attachment-delete="${item.id}">Sil</button></div>`).join('')}
async function saveAttachment(file,transactionId){if(!file||!file.size)return;if(file.size>8*1024*1024)throw new Error('Makbuz dosyası en fazla 8 MB olabilir.');if(!/^image\/(jpeg|png|webp|heic)$|^application\/pdf$/i.test(file.type||''))throw new Error('Yalnızca görsel veya PDF makbuz eklenebilir.');await put('attachments',{id:id(),schemaVersion:1,transactionId,name:file.name.slice(0,140)||'Makbuz',type:file.type||'application/octet-stream',size:file.size,blob:file,lastModified:file.lastModified||Date.now(),createdAt:new Date().toISOString()})}
function viewAttachment(attachmentId){const attachment=state.attachments.find(item=>item.id===attachmentId);if(!attachment?.blob){toast('Makbuz bulunamadı.');return}const url=URL.createObjectURL(attachment.blob),windowRef=window.open(url,'_blank','noopener');if(!windowRef){const link=document.createElement('a');link.href=url;link.download=attachment.name;link.click()}setTimeout(()=>URL.revokeObjectURL(url),60000)}
async function removeAttachment(attachmentId){const attachment=state.attachments.find(item=>item.id===attachmentId);if(!attachment||!confirm(`${attachment.name} silinsin mi?`))return;await remove('attachments',attachmentId);await load();toast('Makbuz silindi')}
