function largeB64(bytes){let binary='';for(let offset=0;offset<bytes.length;offset+=0x8000)binary+=String.fromCharCode(...bytes.subarray(offset,offset+0x8000));return btoa(binary)}
function largeUnb64(value){const binary=atob(value),bytes=new Uint8Array(binary.length);for(let index=0;index<binary.length;index++)bytes[index]=binary.charCodeAt(index);return bytes}
async function blobToBackupValue(blob){const buffer=await blob.arrayBuffer();return {base64:largeB64(new Uint8Array(buffer)),type:blob.type||'application/octet-stream'}}
