function renderBulkControls(){document.querySelectorAll('.txItem[data-edit-id]').forEach(item=>{const idValue=item.dataset.editId,host=item.parentElement;if(!host||host.querySelector(`[data-bulk-select="${idValue}"]`))return;const button=document.createElement('button');button.type='button';button.className='textButton';button.dataset.bulkSelect=idValue;button.setAttribute('aria-label','Hareketi toplu işlem için seç');button.textContent=bulkSelection.has(idValue)?'✓ Seçildi':'Seç';item.after(button)});const status=$('#bulkStatus'),category=$('[data-bulk-category]'),removeButton=$('[data-bulk-delete]'),count=bulkSelection.size;if(status)status.textContent=count?`${count} hareket seçildi.`:'Toplu işlem için hareket seçin.';if(category)category.disabled=!count;if(removeButton)removeButton.disabled=!count}
